CREATE TABLE IF NOT EXISTS horario (
  id_horario INT NOT NULL AUTO_INCREMENT,
  id_ficha INT NOT NULL,
  fecha DATE NOT NULL,
  hora_inicio TIME NOT NULL,
  hora_fin TIME NOT NULL,
  instructor VARCHAR(120) DEFAULT NULL,
  competencia VARCHAR(150) DEFAULT NULL,
  es_festivo TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (id_horario),
  KEY fk_horario_ficha_idx (id_ficha),
  CONSTRAINT fk_horario_ficha FOREIGN KEY (id_ficha) REFERENCES ficha (id_ficha) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

